events.command:
/bin/bash -c 'sort -k1,1 -k2,2n refs/GRCh38-cCREs.bed > refs/GRCh38-cCREs.sorted.bed
for s in S1 S2 S3 S4 S5 S6; do 
  n=$(wc -l < work/${s}.bed); 
  ov=$(bedtools intersect -u -a work/${s}.bed -b refs/GRCh38-cCREs.sorted.bed | wc -l); 
  bp=$(bedtools coverage -a work/${s}.bed -b refs/GRCh38-cCREs.sorted.bed | awk '"'{sum+="'$NF} END{print sum+0}'"'); 
  printf \"%s\\t%s\\t%s\\t%.4f\\t%s\\t%.4f\\n\" \""'$s" "$n" "$ov" "$(awk -v o=$ov -v n=$n '"'BEGIN{print o/n}')\" \""'$bp" "$(awk -v b=$bp -v n=$n '"'BEGIN{print b/(500*n)}')\"; 
done | tee results/ccre_overlap.tsv"

/bin/bash -c "gzip -dc refs/DHS_Index_and_Vocabulary_hg38_WM20190703.txt.gz | awk 'NR>1{print "'$1"'"\\t\""'$2"'"\\t\""'$3"'"\\t\""'$4"'"\\t\""'$6"'"\\t\""'$10}'"' | sort -k1,1 -k2,2n > refs/dhs_index.sorted.bed
wc -l refs/dhs_index.sorted.bed
for s in S1 S2 S3 S4 S5 S6; do 
  n="'$(awk '"'END{print NR}' work/"'${s}.bed); 
  ov=$(bedtools intersect -u -a work/${s}.bed -b refs/dhs_index.sorted.bed | awk '"'END{print NR+0}'); 
  bp="'$(bedtools coverage -a work/${s}.bed -b refs/dhs_index.sorted.bed | awk '"'{sum+="'$7} END{print sum+0}'"'); 
  awk -v s=\""'$s" -v n="$n" -v ov="$ov" -v bp="$bp" '"'BEGIN{printf \"%s\\t%d\\t%d\\t%.5f\\t%d\\t%.5f\\n\",s,n,ov,ov/n,bp,bp/(500*n)}'; 
done | tee results/dhs_index_overlap.tsv"

/bin/bash -c 'for url in https://downloads.wenglab.org/V4/GRCh38-cCREs.bed https://downloads.wenglab.org/V4/GRCh38-cCREs.bed.gz https://downloads.wenglab.org/V4/hg38-cCREs.bed; do echo "$url"; curl -L --silent --show-error --head "$url" | head -5; done
for s in S1 S2 S3 S4 S5 S6; do 
  n=$(awk '"'END{print NR}' work/"'${s}.bed); 
  ov=$(bedtools intersect -u -a work/${s}.bed -b refs/GRCh38-cCREs.sorted.bed | awk '"'END{print NR+0}'); 
  cov="'$(bedtools coverage -a work/${s}.bed -b refs/GRCh38-cCREs.sorted.bed | awk '"'{sum+="'$7} END{print sum+0}'"'); 
  awk -v s=\""'$s" -v n="$n" -v ov="$ov" -v cov="$cov" '"'BEGIN{printf \"%s\\t%d\\t%d\\t%.5f\\t%d\\t%.5f\\n\",s,n,ov,ov/n,cov,cov/(500*n)}'; 
done | tee results/ccre_overlap_clean.tsv"

/bin/bash -c 'curl -L --fail --silent --show-error https://downloads.wenglab.org/V4/GRCh38-cCREs.bed -o refs/GRCh38-cCREs.V4.bed
wc -l refs/GRCh38-cCREs.V4.bed
head -3 refs/GRCh38-cCREs.V4.bed
sort -k1,1 -k2,2n refs/GRCh38-cCREs.V4.bed > refs/GRCh38-cCREs.V4.sorted.bed
for s in S1 S2 S3 S4 S5 S6; do 
  n=$(awk '"'END{print NR}' work/"'${s}.bed); 
  ov=$(bedtools intersect -u -a work/${s}.bed -b refs/GRCh38-cCREs.V4.sorted.bed | awk '"'END{print NR+0}'); 
  cov="'$(bedtools coverage -a work/${s}.bed -b refs/GRCh38-cCREs.V4.sorted.bed | awk '"'{sum+="'$6} END{print sum+0}'"'); 
  awk -v s=\""'$s" -v n="$n" -v ov="$ov" -v cov="$cov" '"'BEGIN{printf \"%s\\t%d\\t%d\\t%.5f\\t%d\\t%.5f\\n\",s,n,ov,ov/n,cov,cov/(500*n)}'; 
done | tee results/ccre_v4_overlap.tsv"
